// Regenerates src/animations.generated.ts from templates/animations/*/meta.json, the single source of
// truth for animation templates and their params. Run after changing a template:
//   node scripts/gen-animations.mjs          (write)
//   node scripts/gen-animations.mjs --check  (exit 1 if the generated file is stale; a test runs this)
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const templatesDir = path.resolve(here, '..', '..', 'templates', 'animations');
const outFile = path.resolve(here, '..', 'src', 'animations.generated.ts');

export function buildTemplates(dir = templatesDir) {
  const out = [];
  for (const id of fs.readdirSync(dir).sort()) {
    if (id.startsWith('_') || id.startsWith('.')) continue;
    const metaPath = path.join(dir, id, 'meta.json');
    if (!fs.existsSync(metaPath)) continue;
    const m = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
    const props = {};
    for (const [k, v] of Object.entries(m.params?.properties ?? {})) {
      if (v.$ref) { props[k] = { ref: v.$ref.split('/').pop() }; continue; }
      const p = { type: v.type };
      for (const key of ['enum', 'description', 'minimum', 'maximum', 'minItems', 'maxItems', 'format', 'default']) {
        if (v[key] !== undefined) p[key] = v[key];
      }
      if (v.items) p.items = { type: v.items.type };
      props[k] = p;
    }
    out.push({
      id: m.id, name: m.name, description: m.description, defaultDuration: m.defaultDuration,
      required: m.params?.required ?? [], params: props,
    });
  }
  return out;
}

export function render(templates) {
  return `// GENERATED by scripts/gen-animations.mjs from templates/animations/*/meta.json. Do not edit.
// A test fails when this file is stale: run \`node scripts/gen-animations.mjs\`.

export interface AnimParamSpec {
  type?: string | string[]; enum?: unknown[]; description?: string; minimum?: number; maximum?: number;
  minItems?: number; maxItems?: number; format?: string; default?: unknown; items?: { type: string }; ref?: string;
}
export interface AnimTemplateSpec {
  id: string; name: string; description: string; defaultDuration: number;
  required: string[]; params: Record<string, AnimParamSpec>;
}

export const ANIMATION_TEMPLATES: AnimTemplateSpec[] = ${JSON.stringify(templates, null, 2)};
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const text = render(buildTemplates());
  if (process.argv.includes('--check')) {
    const cur = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8').replace(/\r\n/g, '\n') : '';
    if (cur !== text) { console.error('src/animations.generated.ts is stale: run node scripts/gen-animations.mjs'); process.exit(1); }
    console.log('animations.generated.ts is up to date');
  } else {
    fs.writeFileSync(outFile, text);
    console.log(`wrote ${outFile}`);
  }
}
